const staticData = $getWorkflowStaticData('global');
if (!staticData.leads) staticData.leads = {};
if (!staticData.conversations) staticData.conversations = {};

const root = $json;
const value = root?.entry?.[0]?.changes?.[0]?.value ?? root?.body?.entry?.[0]?.changes?.[0]?.value ?? root;
const msg = value?.messages?.[0];
if (!msg) return [{json:{ignore:true, reason:'No WhatsApp message found'}}];

const phone = msg.from;
const phoneNumberId = value?.metadata?.phone_number_id ?? 'YOUR_PHONE_NUMBER_ID';
const contactName = value?.contacts?.[0]?.profile?.name ?? 'there';
const text = msg?.text?.body ?? '';
const buttonId = msg?.interactive?.button_reply?.id ?? '';
const listId = msg?.interactive?.list_reply?.id ?? '';
const replyId = buttonId || listId || '';
const pendingBooking = staticData.pendingViewing?.[phone];
const numericSelection = !replyId && /^\s*[1-5]\s*$/.test(text);
const propertyActionMatch = replyId.match(/^(photos|details|viewing)_(.+)$/i);
let property_action = propertyActionMatch ? propertyActionMatch[1].toLowerCase() : '';
let property_id = propertyActionMatch ? propertyActionMatch[2] : '';
let booking_selection = '';
if (numericSelection && pendingBooking) {
  property_action = 'booking_select';
  property_id = pendingBooking.property_id || '';
  booking_selection = String(Number(text.trim()));
}

const buttonMap = {
  rent_property:'I want to rent a property',
  buy_property:'I want to buy a property',
  sell_property:'I want to sell or rent out my property',
  see_all_options:'Show me all options',
  rent_apartment:'I want to rent an apartment',
  rent_villa:'I want to rent a villa',
  buy_apartment:'I want to buy an apartment',
  buy_villa:'I want to buy a villa',
  property_apartment:'Apartment',
  property_villa:'Villa',
  property_townhouse:'Townhouse',
  property_penthouse:'Penthouse',
  bed_studio:'Studio',
  bed_1:'1 Bedroom',
  bed_2:'2 Bedrooms',
  bed_3:'3 Bedrooms',
  timeline_now:'Immediately',
  timeline_1m:'Within 1 month',
  timeline_3m:'Within 3 months',
  timeline_exploring:'Just exploring',
  human_request:'I want to speak with a person'
};

const userText = text.trim() || buttonMap[replyId] || replyId;

let lead = staticData.leads[phone] || {
  phone, name: contactName, language:'', intent:'', purpose:'',
  propertyType:'', bedrooms:'', bathrooms:'', budget:'', currency:'AED',
  area:'', readyOrOffplan:'', paymentMethod:'', timeline:'',
  leadScore:0, temperature:'cold', humanRequested:false, aiPaused:false,
  status:'active', lastUpdated:''
};

lead.name = contactName || lead.name;
lead.lastUpdated = new Date().toISOString();

let history = staticData.conversations[phone] || [];
history.push({role:'user', text:userText, at:new Date().toISOString()});
history = history.slice(-12);
staticData.conversations[phone] = history;

return [{json:{
  ignore:false, phone, phone_number_id:phoneNumberId, contact_name:contactName,
  user_text:userText, reply_id:replyId, property_action, property_id, booking_selection, lead, conversation_history:history
}}];

