const staticData = $getWorkflowStaticData('global');
const input = $('Prepare Conversation').first().json;
let raw = $json.text ?? $json.output ?? $json.response ?? $json.data ?? '';
if (typeof raw !== 'string') raw = JSON.stringify(raw);
raw = raw.trim().replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```$/,'').trim();

let ai;
try {
  ai = JSON.parse(raw);
} catch (e) {
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start >= 0 && end > start) ai = JSON.parse(raw.slice(start,end+1));
  else throw new Error('Gemini did not return valid JSON: ' + raw);
}

const lead = {...input.lead};
const updates = ai.lead_updates || {};
for (const [k,v] of Object.entries(updates)) {
  if (v !== undefined && v !== null && String(v).trim() !== '') lead[k] = v;
}
const previousScore = Number(lead.leadScore || 0);
const delta = Math.max(0, Math.min(30, Number(ai.score_delta || 0)));
lead.leadScore = Math.min(100, previousScore + delta);
if (ai.temperature === 'hot' || lead.leadScore >= 80) lead.temperature = 'hot';
else if (ai.temperature === 'warm' || lead.leadScore >= 45) lead.temperature = 'warm';
else lead.temperature = 'cold';

lead.humanRequested = Boolean(ai.human_requested || lead.humanRequested);
lead.aiPaused = Boolean(ai.ai_paused || lead.aiPaused);
lead.lastUpdated = new Date().toISOString();
if (lead.humanRequested) lead.status = 'human_requested';

staticData.leads[input.phone] = lead;

let history = staticData.conversations[input.phone] || [];
history.push({role:'assistant', text:String(ai.reply || ''), at:new Date().toISOString()});
history = history.slice(-12);
staticData.conversations[input.phone] = history;

return [{json:{
  phone:input.phone, phone_number_id:input.phone_number_id, lead,
  reply:String(ai.reply || 'Thanks. Let me help you with that.'),
  language:ai.language || lead.language || 'en',
  human_requested:Boolean(ai.human_requested || lead.humanRequested),
  ai_paused:Boolean(ai.ai_paused || lead.aiPaused),
  lead_score:lead.leadScore, temperature:lead.temperature, raw_ai:ai
}}];

