const lead = $('Save AI Lead Profile').first().json.lead || {};
const rows = $input.all().map(i => i.json);
const norm=v=>String(v??'').trim().toLowerCase();
const num=v=>{if(v===null||v===undefined||v==='')return NaN;const n=Number(String(v).replace(/[^\d.-]/g,''));return Number.isFinite(n)?n:NaN;};
const beds=v=>{const m=String(v??'').match(/\d+/);return m?Number(m[0]):NaN;};
const intent=norm(lead.intent), type=norm(lead.propertyType), area=norm(lead.area), budget=num(lead.budget), wantedBeds=num(lead.bedrooms), wantedStatus=norm(lead.readyOrOffplan);
function intentOK(r){const x=norm(r.intent);if(!intent)return true;if(!x)return false;if(intent==='buy')return x.includes('buy');if(intent==='rent')return x.includes('rent');return true;}
function score(r){
  if(!intentOK(r))return -999;
  let s=0;
  const ri=norm(r.intent),rt=norm(r.property_type),rc=norm(r.community),ra=norm(r.area),title=norm(r.title),rb=beds(r.bedrooms),price=num(r.price),ready=norm(r.ready_or_offplan),status=norm(r.status);
  if(intent&&ri.includes(intent))s+=40;
  if(type){if(rt===type||rt.includes(type)||type.includes(rt))s+=25;else if(title.includes(type))s+=10;}
  if(area){if(rc===area||ra===area)s+=30;else if(rc.includes(area)||ra.includes(area)||title.includes(area))s+=18;}
  if(Number.isFinite(wantedBeds)&&Number.isFinite(rb)){if(rb===wantedBeds)s+=25;else if(Math.abs(rb-wantedBeds)===1)s+=10;}
  if(Number.isFinite(budget)&&Number.isFinite(price)){if(price<=budget)s+=25;else{const over=(price-budget)/Math.max(budget,1);if(over<=.10)s+=15;else if(over<=.20)s+=5;else s-=10;}}
  if(wantedStatus&&ready&&(ready.includes(wantedStatus)||wantedStatus.includes(ready)))s+=15;
  if(status&&!['available','active','for sale','for rent','ready'].some(x=>status.includes(x)))s-=50;
  return s;
}
const matches=rows.map(row=>({row,score:score(row)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,5);
const saved=$('Save AI Lead Profile').first().json;
if(!matches.length){
  return [{json:{phone:saved.phone,phone_number_id:saved.phone_number_id,property_count:0,no_match:true,property_message:"I checked our current inventory but couldn't find a close match yet. If you share a little more about your preferred area, budget, or property type, I can narrow the search."}}];
}
return matches.map((m,index)=>{
  const p=m.row;
  const price=p.price!==undefined&&p.price!==''?`${p.currency||'AED'} ${p.price}`:'Price on request';
  const body=`🏠 ${p.title||p.property_id||'Property'}\n\n`+
    `💰 ${price}\n`+
    (p.community||p.area?`📍 ${p.community||p.area}\n`:'')+
    (p.bedrooms?`🛏 ${p.bedrooms} bedroom${String(p.bedrooms)==='1'?'':'s'}\n`:'')+
    (p.bathrooms?`🚿 ${p.bathrooms} bathroom${String(p.bathrooms)==='1'?'':'s'}\n`:'')+
    (p.ready_or_offplan?`🏗 ${p.ready_or_offplan}\n`:'')+
    (p.furnished?`🛋 ${p.furnished}\n`:'')+
    (p.payment_plan?`💳 ${p.payment_plan}\n`:'')+
    `\n${p.description||''}`;
  return {json:{
    phone:saved.phone,phone_number_id:saved.phone_number_id,property_count:matches.length,
    property_index:index+1,property_id:p.property_id||'',title:p.title||'',
    price:p.price||'',currency:p.currency||'AED',area:p.area||'',community:p.community||'',
    bedrooms:p.bedrooms||'',bathrooms:p.bathrooms||'',ready_or_offplan:p.ready_or_offplan||'',
    furnished:p.furnished||'',payment_plan:p.payment_plan||'',description:p.description||'',
    photo_1:p.photo_1||'',photo_2:p.photo_2||'',photo_3:p.photo_3||'',video_url:p.video_url||'',
    floor_plan_url:p.floor_plan_url||'',brochure_url:p.brochure_url||'',latitude:p.latitude||'',longitude:p.longitude||'',
    agent_name:p.agent_name||'',agent_email:p.agent_email||'',agent_calendar_email:p.agent_calendar_email||'',
    property_message:body,_match_score:m.score
  }};
});

